def main():
    items,states=base.proposals()
    errors=base.validate(items,states)
    if errors:raise ValueError(errors)
    assert len(items)==200,len(items)
    for item in items:
        item['problem']['authoring']['batch']='engineering-batch4'
        if item['problem']['title']=='Ordinary suspension differs from aborting active queries':
            item['problem']['official_docs']=['https://docs.snowflake.com/en/user-guide/warehouses-tasks','https://docs.snowflake.com/en/sql-reference/sql/alter-warehouse']
    counts={t:sum(p['problem']['tool_id']==t for p in items) for t in states}
    wrapper={'schema_version':1,'proposal_version':'2026.10.26.engineering-batch4','publication_status':'unregistered_proposals',
             'proposals':items,'counts':{'proposed_promotions':len(items),'published_added':0,'by_technology':counts},
             'validation':{'structural_errors':errors,'runtime_claim':'Only fixture contracts authored; learner code and cloud execution remain unverified.'}}
    path=base.OUT/'engineering-promotions4.json';tmp=path.with_suffix('.json.tmp')
    tmp.write_text(json.dumps(wrapper,indent=2,ensure_ascii=False)+'\n',encoding='utf-8',newline='\n');tmp.replace(path)
    checkpoint={'state':'prepared_not_published','proposed':len(items),'published_added':0,'counts':counts,'proposal_sha256':hashlib.sha256(path.read_bytes()).hexdigest(),
                'source_files_sha256':{t:hashlib.sha256(s['path'].read_bytes()).hexdigest() for t,s in states.items()},'errors':errors}
    (base.OUT/'authors/engineering-batch4-checkpoint.json').write_text(json.dumps(checkpoint,indent=2)+'\n',encoding='utf-8')
    print(json.dumps(checkpoint,indent=2))

if __name__=='__main__':main()
